def place(sublist, trail):
    """-> (type, homes, rule) for an item; history and leader periods add the period field."""
    key = "|".join([sublist] + trail[:2])
    best = max((r for r in R if key == r[0] or key.startswith(r[0] + "|")), key=lambda r: len(r[0]), default=None)
    if not best: return None
    typ, homes = best[1], list(best[2])
    if sublist in ("History", "People") and trail and trail[0] in ("Ancient", "Post-classical", "Early modern", "Modern"): homes.append(H[trail[0]])
    if sublist == "People" and len(trail) > 1 and trail[1] in H: homes.append(H[trail[1]])
    if sublist == "History" and len(trail) > 1 and trail[1] == "Colonial empires": homes.append("postcolonial-studies")
    return typ, list(dict.fromkeys(homes)), best[0]
